class Solution:
    # Returns all elements appearing more than one-third of the time.
    def majorityElement(self, nums: list[int]) -> list[int]:
        threshold = len(nums) // 3
        frequency: dict[int, int] = {}
        answer: list[int] = []

        # Store the final frequency of every distinct value.
        for value in nums:
            frequency[value] = frequency.get(value, 0) + 1

        # Arrange the completed map entries in ascending key order.
        ordered_frequency: dict[int, int] = dict(sorted(frequency.items()))

        # Inspect each distinct value directly in ascending key order.
        for value, count in ordered_frequency.items():
            # Store the value when its final frequency crosses the threshold.
            if count > threshold:
                answer.append(value)

            # At most two distinct values can satisfy the condition.
            if len(answer) == 2:
                break

        return answer


